import {exercises,exerciseById,groups,equipmentLabels} from './data.js';
import {muscleStats,within,addDays,dailyCalories,correlation,performance,weightTrend,smoothWeight,workSets} from './science.js';
import {TODAY,uid} from './store.js';
import {esc,btn,empty,field,select,num,dateLabel,metric,modal,chart,toast} from './ui.js';
const eligible=(C,e)=>e.equipment.every(x=>x==='bodyweight'||C.state.profile.equipment.includes(x));
export function planView(C){const p=C.state.profile,start=C.ui.scheduleStart||TODAY(),planDays=Array.from({length:7},(_,i)=>addDays(start,i)),schedule=C.state.schedule.filter(s=>s.date>=TODAY()).sort((a,b)=>a.date.localeCompare(b.date)),recommendations=planRecommendations(C);return `<div class="page-head"><div><h1>Plan</h1></div>${btn('Create a routine','routine-new','primary','plus')}</div><div class="grid two"><div class="stack"><section class="card"><div class="card-head"><h2>Week</h2><input class="search day-selector" type="date" name="schedule-start" value="${start}" aria-label="Week starting date"></div>${C.state.routines.length?`<form id="schedule-form">${planDays.map(date=>`<div class="schedule-day"><div class="split-header"><h3>${dateLabel(date,{weekday:'long',month:'short',day:'numeric'})}</h3><small>${C.state.sessions.some(s=>s.date===date)?'Workout recorded':''}</small></div>${select('day-'+date,'Routine',C.state.schedule.find(s=>s.date===date)?.routineId||'',[['','Rest / no scheduled workout'],...C.state.routines.map(r=>[r.id,r.name])])}</div>`).join('')}<label class="check"><input type="checkbox" name="repeat">Repeat these seven days for 4 weeks</label><button class="btn primary" type="submit">Save schedule</button></form>`:empty('No routines yet','Create one, or generate a starter routine from your equipment.','routine-new','Create routine')}</section><section class="card"><h2>Upcoming</h2>${schedule.length?schedule.slice(0,16).map(s=>`<div class="row"><div><strong>${esc(C.state.routines.find(r=>r.id===s.routineId)?.name)}</strong><p>${dateLabel(s.date,{weekday:'short',month:'short',day:'numeric'})}</p></div><div class="row-actions">${btn('Start','start-routine:'+s.routineId,'small')}${btn('Remove','remove-schedule:'+s.id,'small danger')}</div></div>`).join(''):empty('No scheduled sessions','Select routines above and save a schedule.')}</section></div><div class="stack"><section class="card accent-card"><div class="eyebrow">Starter routine</div><h2>Build one from your equipment</h2><p>${p.days} available training days · ${p.experience} · ${p.equipment.map(x=>equipmentLabels[x]).join(', ')}</p>${btn('Create suggested routines','generate-plan')}<p style="margin:12px 0 0">Every exercise and target stays editable.</p></section><section class="card"><h2>Principles behind it</h2>${recommendations.map(r=>`<div class="reference"><h3>${r.title}</h3><p>${r.text}</p><small>${r.kind} · ${C.sourceLinks(r.sources)}</small></div>`).join('')}${p.limitations?`<div class="notice warning"><strong>Your limitations</strong><p>${esc(p.limitations)}</p><small>The local rules do not interpret injuries or medical restrictions. Review exercise suitability before using a suggested routine.</small></div>`:''}</section><section class="card"><h2>Progression</h2>${C.state.sessions.length?`<p class="note-box">Your exercise-performance page checks whether recent comparable sets justify considering a load change. Recommendations are never applied automatically.</p>${btn('Review performance','go-training','small')}`:empty('No sessions yet','Load suggestions appear after two comparable sessions.')}<details class="fine"><summary>About this</summary><p>No spot reduction, muscle-confusion schedule, or claimed perfect recovery score is used.</p></details></section></div></div>`}
function planRecommendations(C){const p=C.state.profile,stats=muscleStats(C.state.sessions,exercises,groups,TODAY(),7),neglected=groups.filter(g=>stats[g.id].primary===0);const r=[{title:'Train progressively and consistently',text:'Progressive resistance training improves strength and muscle growth. Two or more weekly sessions are a useful general starting point. The right dose depends on your experience, goals and tolerance.',kind:'Evidence-supported principle',sources:['acsm2026']},{title:p.goal==='strength'?'Practice the lifts you want to improve':p.goal==='muscle-growth'||p.goal==='recomposition'?'Build volume gradually':'Start with a manageable dose',text:p.goal==='strength'?'Heavier loads can benefit strength. This app starts with editable set and repetition targets; it cannot choose a safe working load from your profile alone.':p.goal==='muscle-growth'||p.goal==='recomposition'?'Higher weekly volume can enhance hypertrophy, but a threshold such as 10 sets per group is not a universal requirement or optimum. Start below what you cannot recover from and adjust from performance.':'Simple routines covering a knee-dominant movement, hinge, push, pull and trunk work provide a practical starting structure. The exact selection and dose are app heuristics.',kind:p.goal==='general'?'Programming heuristic':'Evidence with individual uncertainty',sources:['acsm2026']},{title:'Effort without mandatory failure',text:'Record RIR to learn how hard sets feel. Stopping short of failure can still support muscle growth. An initial 2–3 RIR target is a conservative coaching choice, not a guaranteed optimum.',kind:'Evidence + disclosed coaching choice',sources:['refalo2024','zourdos2016']},{title:'Keep aerobic movement in the week',text:'Aim toward the adult WHO activity guidelines at a sustainable pace. If endurance is the main goal, increase duration gradually and use the activity history and talk test to guide intensity.',kind:'Authoritative guidance',sources:['who2020','cdc_intensity2025']}];if(['fat-loss','maintenance','recomposition'].includes(p.goal))r.push({title:'Review the weight trend, not a single day',text:'Body weight varies for reasons other than fat change. Review complete calorie logs and repeated weigh-ins before changing intake. The app avoids fixed calorie-to-weight timelines.',kind:'Modeling evidence + monitoring heuristic',sources:['hall2011']});if(C.state.sessions.length)r.push({title:'Review training balance',text:neglected.length?'No primary working sets were logged for '+neglected.slice(0,4).map(g=>g.name).join(', ')+' in the last seven days. This is a record-coverage observation, not a diagnosis of inadequate training.':'All tracked groups have primary work recorded this week. More sets are not automatically better.',kind:'Observation from your log',sources:['acsm2026']});return r}
function suggested(C){const p=C.state.profile;const choose=ids=>ids.map(exerciseById).find(e=>e&&eligible(C,e))?.id;let patterns=p.goal==='mobility'?[['calf-stretch'],['hip-flexor-mobility'],['thoracic-rotation']]:[['goblet-squat','barbell-squat','bodyweight-squat'],['dumbbell-rdl','romanian-deadlift','glute-bridge'],['dumbbell-bench','bench-press','push-up'],['cable-row','dumbbell-row','band-row','inverted-row','lat-pulldown','pull-up'],['dead-bug','plank']];const selected=patterns.map(choose).filter(Boolean),sets=p.goal==='mobility'?1:p.experience==='beginner'?2:3,reps=p.goal==='strength'?5:10;return {selected,sets,reps,missing:patterns.length-selected.length}}
export async function planAction(a,id,C){if(a==='generate-plan'){const v=suggested(C);if(!v.selected.length)throw Error('No supported movements match the equipment. Review Settings.');modal('Your suggested starting routine',`<p class="note-box">The exercises match your selected equipment. Targets are a programming starting point, not an individually validated optimum.</p>${v.selected.map(id=>`<div class="row"><strong>${esc(exerciseById(id).name)}</strong><span>${v.sets} sets${exerciseById(id).tracking==='reps-load'?' × '+v.reps+' reps':' · choose a controlled duration'}</span></div>`).join('')}${v.missing?'<div class="notice warning">A movement pattern has no matching equipment. The routine does not cover that pattern; review the library or add equipment before treating it as a complete strength plan.</div>':''}<p class="meta">Use manageable loads. Start with effort to spare, and revise the targets from your records. Schedule at least two strength days when suitable; leave time between demanding sessions as needed.</p>${field('name','Routine name',C.state.profile.goal==='mobility'?'Mobility essentials':'Full body · foundations','text','required maxlength="100"')}`,async fd=>{C.state.routines.push({id:uid(),name:fd.get('name').trim(),restSeconds:120,exercises:v.selected.map(id=>({exerciseId:id,sets:v.sets,reps:exerciseById(id).tracking==='reps-load'?v.reps:0,duration:exerciseById(id).tracking==='reps-load'?null:30}))});await C.save('Suggested routine created')});return true}if(a==='remove-schedule'){C.state.schedule=C.state.schedule.filter(s=>s.id!==id);await C.save('Scheduled session removed');return true}return false}
export function insightsView(C){const days=C.ui.insightDays||28,end=TODAY(),previousEnd=addDays(end,-days),current=C.state.sessions.filter(x=>within(x.date,end,days)),previous=C.state.sessions.filter(x=>within(x.date,previousEnd,days)),currentIntake=dailyCalories(C.state.calories,C.state.calorieDays,end,days).filter(x=>x.complete),previousIntake=dailyCalories(C.state.calories,C.state.calorieDays,previousEnd,days).filter(x=>x.complete),mean=arr=>arr.length?arr.reduce((a,x)=>a+x.value,0)/arr.length:null,weights=C.state.weights.filter(x=>within(x.date,end,days)),trend=weightTrend(weights,end,days),cardio=C.state.cardio.filter(x=>within(x.date,end,days)),selected=C.ui.insightExercise||C.recentExercise(),perf=performance(current,selected),paired=C.state.wellbeing.filter(x=>within(x.date,end,days)&&x.sleep!==null&&x.soreness!==null).map(x=>[x.sleep,x.soreness]),corr=correlation(paired),calWeight=currentIntake.flatMap(c=>{const w=weights.find(w=>w.date===c.date);return w?[[c.value,w.kg]]:[]}),intakeCorr=correlation(calWeight);return `<div class="page-head"><div><h1>Insights</h1></div><div class="button-group">${[7,28,90].map(n=>btn(n+' days','insight-period:'+n,'small '+(days===n?'primary':''))).join('')}</div></div><div class="metrics">${metric('Training sessions',current.length,'',current.length-previous.length>=0?'+'+(current.length-previous.length)+' vs previous period':(current.length-previous.length)+' vs previous period','training')}${metric('Average complete-day intake',num(mean(currentIntake)),'kcal',currentIntake.length+'/'+days+' complete days · prior '+num(mean(previousIntake)),'calories')}${metric('Weight trend',trend?num(C.displayWeight(trend.weekly),2):'—',C.weightUnit()+'/week',trend?trend.n+' weigh-ins · no fat-change inference':'Insufficient trend data','weight')}${metric('Cardio time',num(cardio.reduce((a,x)=>a+x.duration,0)),'min',num(C.state.cardio.filter(x=>within(x.date,previousEnd,days)).reduce((a,x)=>a+x.duration,0))+' min in prior period','cardio')}</div><div class="grid equal"><section class="card"><div class="card-head"><h2>Weekly muscle work</h2><span class="badge">Last 7 days</span></div>${C.volumeBars(7)}<details class="fine"><summary>About this</summary><p>Each completed non-warm-up strength set is counted for assigned primary groups. Secondary exposure is separate, with no fractional set weighting. Stabilizers are excluded. Group totals are not additive. ${C.sourceLinks(['acsm2026'])}</p></details></section><section class="card"><h2>Muscle-group history</h2>${select('insight-muscle','Muscle group',C.ui.insightMuscle||'chest',groups.map(g=>[g.id,g.name]))}${chart(muscleBins(C,C.ui.insightMuscle||'chest',end,days),{unit:'Primary sets per week',bars:true})}<details class="fine"><summary>About this</summary><p>Non-warm-up primary strength-set exposures, in consecutive 7-day bins within the selected period. Secondary work is shown separately in the weekly balance.</p></details></section><section class="card"><h2>Strength progression</h2>${select('insight-exercise','Movement',selected,exercises.filter(e=>e.category==='strength').map(e=>[e.id,e.name]))}${chart(perf.filter(x=>x.load!==null).map(x=>({date:x.date,value:C.displayLoad(x.load)})),{unit:'Best load ('+C.loadUnit()+')'})}<details class="fine"><summary>About this</summary><p>Exercise-specific best completed working-set load. Assisted, machine, and bodyweight records need consistent load conventions.</p></details></section><section class="card"><h2>Intake & weight</h2><h3>Daily intake · complete days</h3>${chart(currentIntake,{unit:'kcal/day',bars:true,height:190})}<h3 class="subsection">Smoothed weight</h3>${chart(smoothWeight(weights).map(x=>({...x,value:C.displayWeight(x.value)})),{unit:C.weightUnit(),height:190})}<details class="fine"><summary>About this</summary><p>Separate scales prevent implying that calorie and weight magnitudes are directly comparable. Same-day Pearson correlation: ${intakeCorr?'r = '+num(intakeCorr.r,2)+' across '+intakeCorr.n+' paired days':'not available (needs at least 7 paired observations and variation)'}. Day-to-day association does not establish an energy-balance mechanism or causation.</p></details></section><section class="card"><h2>Workout consistency</h2>${chart(sessionBins(current,end,days),{unit:'Sessions per week',bars:true,height:190})}<h3 class="subsection">Goals & adherence</h3><div class="row"><span>Scheduled dates in period</span><strong>${C.state.schedule.filter(x=>within(x.date,end,days)).length}</strong></div><div class="row"><span>Scheduled dates with a session</span><strong>${C.state.schedule.filter(x=>within(x.date,end,days)&&current.some(s=>s.date===x.date)).length}</strong></div><div class="row"><span>Complete calorie days within ±10% target</span><strong>${currentIntake.filter(x=>Math.abs(x.value-C.state.profile.calorieTarget)<=C.state.profile.calorieTarget*.1).length} / ${currentIntake.length}</strong></div><details class="fine"><summary>About this</summary><p>The ±10% band is an app display convention, not a scientifically validated adherence threshold. Schedule completion means any session was recorded on the planned date.</p></details></section><section class="card"><h2>Cardio performance</h2>${select('insight-cardio','Activity',C.ui.insightCardio||'Running',['Walking','Running','Cycling','Rowing','Swimming','Hiking','Other'])}${chart(cardio.filter(x=>x.type===(C.ui.insightCardio||'Running')&&x.distance>0).sort((a,b)=>a.date.localeCompare(b.date)).map(x=>({date:x.date,value:x.duration/C.displayDist(x.distance)})),{unit:'Pace (min/'+C.distUnit()+')'})}<details class="fine"><summary>About this</summary><p>Pace comparisons depend on route, conditions, effort and distance. A faster pace alone does not measure cardiovascular fitness.</p></details></section><section class="card"><h2>Sleep & soreness</h2>${corr?`<div class="large-number">r = ${num(corr.r,2)}</div><p class="note-box">Pearson association across ${corr.n} days with both sleep and soreness recorded.</p>`:empty('More paired observations needed','At least 7 days with both sleep and soreness, and variation in both, are required.')}<details class="fine"><summary>About this</summary><p>Correlation is descriptive, not proof that one variable caused the other. Soreness is an ordinal self-rating; treating its steps as equal intervals is a display assumption. Small samples, missing records and shared causes can mislead.</p></details>${C.sourceLinks(['aasm_sleep2015'])}</section></div><section class="card subsection"><h2>Personal records</h2>${prTable(C)}<details class="fine"><summary>About this</summary><p>Records are computed from actual completed working sets. Estimated 1RM requires a qualifying low-repetition maximum-effort set; it is not a tested 1RM.</p></details></section>`}
function sessionBins(sessions,end,days){const n=Math.ceil(days/7);return Array.from({length:n},(_,i)=>{const weekEnd=addDays(end,-7*(n-1-i));return {date:weekEnd,value:sessions.filter(x=>within(x.date,weekEnd,7)).length}})}
function prTable(C){const records=exercises.filter(e=>e.category==='strength').map(e=>({e,h:performance(C.state.sessions,e.id)})).filter(x=>x.h.length);if(!records.length)return empty('No records yet','Finish a workout to see your bests.');return `<div class="table-wrap"><table class="data-table"><thead><tr><th>Exercise</th><th>Best load</th><th>Best reps</th><th>Estimated 1RM</th><th>Sessions</th></tr></thead><tbody>${records.map(({e,h})=>{const estimates=h.filter(x=>x.e1rm!==null);return `<tr><td><button class="text-link" data-action="exercise:${e.id}">${esc(e.name)}</button></td><td>${num(C.displayLoad(h.some(x=>x.load!==null)?Math.max(...h.filter(x=>x.load!==null).map(x=>x.load)):null),1)} ${C.loadUnit()}</td><td>${num(h.some(x=>x.reps!==null)?Math.max(...h.filter(x=>x.reps!==null).map(x=>x.reps)):null)}</td><td>${estimates.length?num(C.displayLoad(Math.max(...estimates.map(x=>x.e1rm))),1)+' '+C.loadUnit():'—'}</td><td>${h.length}</td></tr>`}).join('')}</tbody></table></div>`}

function muscleBins(C,id,end,days){const n=Math.ceil(days/7),first=addDays(end,-days+1),sessions=C.state.sessions.filter(s=>s.date>=first&&s.date<=end);return Array.from({length:n},(_,i)=>{const weekEnd=addDays(end,-7*(n-1-i));return {date:weekEnd,value:muscleStats(sessions,exercises,groups,weekEnd,7)[id]?.primary||0}})}
